def transform(grid):
    """Expand a centered top-edge 2 into diagonal rays and fill periodic inner diagonals."""
    n = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0 for _ in range(n)] for _ in range(n)]
    for r in range(n):
        left = center - r
        right = center + r
        if 0 <= left < n:
            out[r][left] = 2
        if 0 <= right < n:
            out[r][right] = 2
        lo = max(0, left)
        hi = min(n - 1, right)
        for c in range(lo + 1, hi):
            if (c - r) % 4 == 2:
                out[r][c] = 1
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))

