def transform(grid):
    """Generate the diagonal V of 2s, then continue diagonal stripes of 1s."""
    n = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2
    # The stripes of 1 begin beneath the third row of the V. Their phase is
    # opposite (modulo 4) to the V's diagonal phase.
    phase = (center + 2) % 4
    for r in range(3, n):
        for c in range(n):
            if (c - r) % 4 == phase:
                out[r][c] = 1
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))

def transform(grid):
    """Expand a central top marker into a V and continue its periodic interior stripe."""
    n = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2
    # In the demonstrations, the 1-stripe is c-r == 2 (mod 4), below row 2.
    for r in range(3, n):
        for c in range(n):
            if (c - r) % 4 == 2:
                out[r][c] = 1
    return out

if __name__ == "__main__":
