def transform(grid):
    """Collapse vertically stacked equal-sized panels by taking the first nonzero cell."""
    height = len(grid)
    if height == 0 or height % 4:
        raise ValueError("expected four equal-height panels")
    panel_height = height // 4
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("grid must be rectangular")
    output = [[0 for _ in range(width)] for _ in range(panel_height)]
    for panel in range(4):
        for r in range(panel_height):
            for c in range(width):
                value = grid[panel * panel_height + r][c]
                if output[r][c] == 0 and value != 0:
                    output[r][c] = value
    return output

