    h, w = len(grid), len(grid[0])
    # Find the horizontal palette sequence repeated on at least two rows.
    palette = None
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] != 0:
                c += 1
            seq = grid[r][a:c]
            if len(seq) < 2:
                continue
            end = r + 1
            while end < h and grid[end][a:a + len(seq)] == seq:
                end += 1
            if end - r >= 2:
                palette = (seq[:], r, end, a, a + len(seq))
                break
        if palette is not None:
            break
    if palette is None:
        return [row[:] for row in grid]

    seq, pr0, pr1, pc0, pc1 = palette
    anchor_color = 1 if 1 in seq else seq[len(seq) // 2]
    anchor_index = seq.index(anchor_color)

    # Extract the anchor-color motif, separating it from its palette strip.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != anchor_color or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == dx == 0:
                            continue
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                                (yy, xx) not in seen and grid[yy][xx] == anchor_color):
                            seen.add((yy, xx))
                            stack.append((yy, xx))
            if any(not (pr0 <= y < pr1 and pc0 <= x < pc1) for y, x in comp):
                components.append(comp)
    if not components:
        return [row[:] for row in grid]

    motif = max(components, key=len)
    top = min(y for y, x in motif)
    left = min(x for y, x in motif)
    step = max(y for y, x in motif) - top + 1
    points = [(y - top, x - left) for y, x in motif]

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(seq):
        shift = (i - anchor_index) * step
        for dy, dx in points:
            y, x = top + shift + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out

