def transform(grid):
    """Extend a seeded diagonal segment through empty cells in both directions."""
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seeds = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    seeds.append((r, c, dr, dc, color))
    for r, c, dr, dc, color in seeds:
        for direction in (-1, 1):
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                value = grid[rr][cc]
                if value not in (background, color):
                    break
                if value == background:
                    out[rr][cc] = color
                rr += direction * dr
                cc += direction * dc
    return out


