from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # A diagonal pair marks a line. Extend through background in each
    # direction, stopping at the first cell belonging to another object/color.
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    key = (r, c, dr, dc, color)
                    if key in seen:
                        continue
                    seen.add(key)
                    for sign in (-1, 1):
                        y, x = r, c
                        while 0 <= y < h and 0 <= x < w:
                            if grid[y][x] != background and grid[y][x] != color:
                                break
                            if grid[y][x] == background:
                                out[y][x] = color
                            y += sign * dr
                            x += sign * dc
    return out


