def transform(grid):
    """Complete the most-supported rectangular frame of the marker scaffold."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    colors = [v for v in counts if v != bg]
    if not colors:
        return [row[:] for row in grid]
    marker = max(colors, key=lambda v: counts[v])
    pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker}
    if not pts:
        return [row[:] for row in grid]

    # Candidate sides are clue rows/columns. Prefer rectangles whose corners
    # are explicitly marked and whose sides have the strongest marker support.
    rs = sorted({r for r, _ in pts})
    cs = sorted({c for _, c in pts})
    best = None
    for i, top in enumerate(rs):
        for bottom in rs[i + 1:]:
            for j, left in enumerate(cs):
                for right in cs[j + 1:]:
                    corners = sum((r, c) in pts for r in (top, bottom) for c in (left, right))
                    if corners < 3:
                        continue
                    perimeter = sum((r, c) in pts for c in range(left, right + 1) for r in (top, bottom))
                    perimeter += sum((r, c) in pts for r in range(top + 1, bottom) for c in (left, right))
                    outside = sum(not (top <= r <= bottom and left <= c <= right) for r, c in pts)
                    score = (corners, perimeter, -outside, (bottom-top)*(right-left))
                    if best is None or score > best[0]:
                        best = (score, top, bottom, left, right)
    out = [row[:] for row in grid]
    if best is None:
        return out
    _, top, bottom, left, right = best

    for c in range(left, right + 1):
        if grid[top][c] == bg:
            out[top][c] = 2
        if grid[bottom][c] == bg:
            out[bottom][c] = 2
    for r in range(top, bottom + 1):
        if grid[r][left] == bg:
            out[r][left] = 2
        if grid[r][right] == bg:
            out[r][right] = 2

    # Also bridge same-color clues along straight lines contained by the frame.
    for c in range(left + 1, right):
        rows = [r for r in range(top + 1, bottom) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for r in range(top + 1, bottom):
        cols = [c for c in range(left + 1, right) if grid[r][c] == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out


