def transform(grid):
    """Complete the best-supported rectangular marker frame in color 2."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    colors = [value for value in counts if value != background]
    if not colors:
        return [row[:] for row in grid]
    marker = max(colors, key=lambda value: counts[value])
    points = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == marker}
    rows = sorted({r for r, _ in points})
    cols = sorted({c for _, c in points})

    # The intended frame is supported by at least three of its four corners,
    # with evidence on every side. Choose the frame with strongest boundary
    # support, rather than using unrelated outlying markers as global bounds.
    candidates = []
    for ti, top in enumerate(rows):
        for bottom in rows[ti + 1:]:
            for li, left in enumerate(cols):
                for right in cols[li + 1:]:
                    sides = (
                        [(top, c) for c in range(left, right + 1)],
                        [(bottom, c) for c in range(left, right + 1)],
                        [(r, left) for r in range(top, bottom + 1)],
                        [(r, right) for r in range(top, bottom + 1)],
                    )
                    hits = [sum(p in points for p in side) for side in sides]
                    corner_count = sum((r, c) in points
                                       for r in (top, bottom)
                                       for c in (left, right))
                    if corner_count < 3 or min(hits) < 2:
                        continue
                    boundary_hits = sum(hits) - corner_count
                    outside = sum(not (top <= r <= bottom and left <= c <= right)
                                  for r, c in points)
                    area = (bottom - top + 1) * (right - left + 1)
                    # Favor four-corner frames, then repeated boundary clues;
                    # mildly prefer broader support and fewer external markers.
                    score = (corner_count, boundary_hits, min(hits), -outside, area)
                    candidates.append((score, top, bottom, left, right))

    out = [row[:] for row in grid]
    if not candidates:
        return out
    _, top, bottom, left, right = max(candidates)
    for c in range(left, right + 1):
        if grid[top][c] == background:
            out[top][c] = 2
        if grid[bottom][c] == background:
            out[bottom][c] = 2
    for r in range(top, bottom + 1):
        if grid[r][left] == background:
            out[r][left] = 2
        if grid[r][right] == background:
            out[r][right] = 2
    return out


