                               + (grid[r][c] == color))
        candidates = []
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                height = r1 - r0 + 1
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = height * (c1 - c0 + 1)
                        count = p[r1+1][c1+1] - p[r0][c1+1] - p[r1+1][c0] + p[r0][c0]
                        if count >= 0.80 * area:
