def transform(grid):
    """Remove isolated speckles and fill interior gaps in same-color panels."""
    h, w = len(grid), max(map(len, grid))
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    a = [list(row) + [bg] * (w - len(row)) for row in grid]
    out = [row[:] for row in a]
    # Discard connected components that are isolated one-cell contaminants.
    seen = set()
    for r in range(h):
        for c in range(w):
            col = a[r][c]
            if col == bg or (r,c) in seen:
                continue
            q = deque([(r,c)]); seen.add((r,c)); comp=[]
            while q:
                x,y=q.popleft(); comp.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and a[nx][ny]==col and (nx,ny) not in seen:
                        seen.add((nx,ny));q.append((nx,ny))
            if len(comp)==1:
                out[r][c]=bg
    # Iterate only filling cells strongly surrounded by a sufficiently large
    # same-color patch; prevents colored clue specks from growing into objects.
    while True:
        additions=[]
        colors=set(v for row in out for v in row if v != bg)
        for r in range(h):
            for c in range(w):
                if out[r][c] != bg:
                    continue
                for col in colors:
                    orth=sum(0<=rr<h and 0<=cc<w and out[rr][cc]==col
                             for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)))
                    diag=sum(0<=rr<h and 0<=cc<w and out[rr][cc]==col
                             for rr,cc in ((r-1,c-1),(r-1,c+1),(r+1,c-1),(r+1,c+1)))
                    amount=sum(v==col for row in out for v in row)
                    if orth>=2 and diag>=1 and amount>=10:
                        additions.append((r,c,col)); break
        if not additions:
            break
