"""Infer panel colors from similarity to the densest 4x4 panel."""


def transform(grid):
    """Recolor the densest panel 3 and its two closest distinct motifs 8."""
    out = [row[:] for row in grid]
    panels = []
    for r0 in (1, 6, 11):
        for c0 in (1, 6):
            cells = [(r, c) for r in range(r0, r0 + 4)
                     for c in range(c0, c0 + 4) if grid[r][c] == 2]
            mask = tuple(tuple(1 if grid[r][c] == 2 else 0
                               for c in range(c0, c0 + 4))
                         for r in range(r0, r0 + 4))
            panels.append((r0, c0, cells, mask))

    # The uniquely densest panel is the reference (color 3).
    densest = max(range(len(panels)), key=lambda i: len(panels[i][2]))
    ref = panels[densest]
    for r, c in ref[2]:
        out[r][c] = 3

    # Color 8 the two closest *distinct* panel masks. When several panels
    # share the same distance and motif, keep the first occurrence only.
    candidates = sorted(
        (sum(ref[3][r][c] != panel[3][r][c]
             for r in range(4) for c in range(4)), i, panel)
        for i, panel in enumerate(panels) if i != densest
    )
    chosen_masks = set()
    chosen = 0
    for _, _, panel in candidates:
        if panel[3] in chosen_masks:
            continue
        chosen_masks.add(panel[3])
        for r, c in panel[2]:
            out[r][c] = 8
        chosen += 1
        if chosen == 2:
            break
    return out

"""Find a 4x4 panel that is the union of two other panels."""


def transform(grid):
    out = [row[:] for row in grid]
    starts = [(r, c) for r in (1, 6, 11) for c in (1, 6)]
    masks = []
    for r0, c0 in starts:
        masks.append(tuple(tuple(grid[r0 + dr][c0 + dc] == 2
                                 for dc in range(4))
                           for dr in range(4)))

    # In the demonstrations one panel combines two other panels cellwise.
    # Recolor the composite 3 and its two contributing panels 8.
    for target, whole in enumerate(masks):
        for first in range(len(masks)):
            if first == target:
                continue
            for second in range(first + 1, len(masks)):
                if second == target:
                    continue
                if all(whole[r][c] == (masks[first][r][c] or masks[second][r][c])
                       for r in range(4) for c in range(4)):
                    for idx, color in ((target, 3), (first, 8), (second, 8)):
                        r0, c0 = starts[idx]
                        for dr in range(4):
                            for dc in range(4):
                                if masks[idx][dr][dc]:
                                    out[r0 + dr][c0 + dc] = color
                    return out
    return out


