    out = [row[:] for row in grid]
    starts = [(r, c) for r in (1, 6, 11) for c in (1, 6)]
    masks = [tuple(tuple(grid[r0 + dr][c0 + dc] for dc in range(4))
                   for dr in range(4)) for r0, c0 in starts]
    sizes = [sum(cell != 0 for row in mask for cell in row) for mask in masks]
    # The uniquely densest of the six panels is the reference (color 3).
    ref = max(range(6), key=lambda i: sizes[i])
    # Two panels most similar to that reference are colored 8. Raster order
    # resolves equal-distance ties, as in the demonstrations.
    distances = [sum(masks[i][r][c] != masks[ref][r][c]
                     for r in range(4) for c in range(4))
                 for i in range(6)]
    nearest = sorted((distances[i], i) for i in range(6) if i != ref)[:2]
    colors = {ref: 3, **{i: 8 for _, i in nearest}}
    for idx, color in colors.items():
        r0, c0 = starts[idx]
        for dr in range(4):
            for dc in range(4):
                if grid[r0 + dr][c0 + dc] != 0:
                    out[r0 + dr][c0 + dc] = color
    return out

