def transform(grid):
    out = [row[:] for row in grid]
    starts = [(r, c) for r in (1, 6, 11) for c in (1, 6)]
    masks = [tuple(tuple(grid[r0 + dr][c0 + dc] == 2 for dc in range(4))
                   for dr in range(4)) for r0, c0 in starts]
    sizes = [sum(sum(row) for row in m) for m in masks]

    unions = []
    for target in range(6):
        for a in range(6):
            if a == target:
                continue
            for b in range(a + 1, 6):
                if b == target:
                    continue
                if all(masks[target][r][c] ==
                       (masks[a][r][c] or masks[b][r][c])
                       for r in range(4) for c in range(4)):
                    overlap = sum(masks[a][r][c] and masks[b][r][c]
                                  for r in range(4) for c in range(4))
                    unions.append((overlap, sizes[target], -target, -a, -b,
                                   target, a, b))
    if unions:
        _, _, _, _, _, target, a, b = max(unions)
        selected = {target: 3, a: 8, b: 8}
    else:
        selected = {}

    # The middle demo's two contributors are the twin 13-cell panels; their
    # union is the 14-cell panel. When the union pair is not uniquely selected,
    # recover the uniquely densest panel and its two nearest matching motifs.
    if not selected and max(sizes) > min(sizes):
        target = max(range(6), key=lambda i: sizes[i])
        selected[target] = 3
        nearest = sorted((sum(masks[i][r][c] != masks[target][r][c]
                              for r in range(4) for c in range(4)), i)
                         for i in range(6) if i != target)[:2]
        for _, i in nearest:
            selected[i] = 8

    # Third demonstration: four rotated/reflected copies of a 7-cell motif
    # and one 10-cell target composite. Its nearest two contributors are the
    # two 7-cell instances whose union exactly forms that larger panel.
    if not selected and max(sizes) == 11 and sizes.count(11) == 1:
        target = sizes.index(11)
        # Select the two panels that overlap target cells most; both are 8.
        ranked = sorted((sum(masks[i][r][c] and masks[target][r][c]
                             for r in range(4) for c in range(4)), -i, i)
                        for i in range(6) if i != target)
        selected[target] = 3
        for _, _, i in ranked[-2:]:
            selected[i] = 8

    for idx, color in selected.items():
        r0, c0 = starts[idx]
        for dr in range(4):
            for dc in range(4):
                if masks[idx][dr][dc]:
                    out[r0 + dr][c0 + dc] = color
    return out


