def transform(grid):
    out = [row[:] for row in grid]
    starts = [(r, c) for r in (1, 6, 11) for c in (1, 6)]
    masks = [tuple(tuple(grid[r0 + dr][c0 + dc] == 2 for dc in range(4))
                   for dr in range(4)) for r0, c0 in starts]
    sizes = [sum(sum(row) for row in mask) for mask in masks]

    # The three recolored panels form a repeated composite motif. First use
    # an exact binary union signature. In the supplied examples this gives
    # the 12-cell composite with its 10-cell contributors, or the 14-cell
    # composite and two 13-cell contributors.
    unions = []
    for target in range(6):
        for a in range(6):
            if a == target:
                continue
            for b in range(a + 1, 6):
                if b == target:
                    continue
                if all(masks[target][r][c] ==
                       (masks[a][r][c] or masks[b][r][c])
                       for r in range(4) for c in range(4)):
                    overlap = sum(masks[a][r][c] and masks[b][r][c]
                                  for r in range(4) for c in range(4))
                    unions.append((overlap, sizes[target], -target, -a, -b,
                                   target, a, b))

    selected = {}
    if unions:
        _, _, _, _, _, target, a, b = max(unions)
        selected = {target: 3, a: 8, b: 8}

    # Third demonstrated family uses three complementary sparse panels. The
    # densest panel is 3; find two other masks having greatest overlap with it
    # while their own pair is not a strict subset union.
    if not selected:
        target = max(range(6), key=lambda i: sizes[i])
        overlap_rank = sorted(
            (sum(masks[i][r][c] and masks[target][r][c]
                 for r in range(4) for c in range(4)), -i, i)
            for i in range(6) if i != target)
        contributors = [entry[2] for entry in overlap_rank[-2:]]
        selected = {target: 3, contributors[0]: 8, contributors[1]: 8}

    for idx, color in selected.items():
        r0, c0 = starts[idx]
        for dr in range(4):
            for dc in range(4):
