from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next((c for c in range(1, w - 1)
                if all(grid[r][c] == grid[0][c] for r in range(h))), None)
    if sep is None:
        raise ValueError("no solid separator column")
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    if any(len(left[r]) != len(right[r]) for r in range(h)):
        raise ValueError("panels differ in width")
    mismatch = Counter(v for row in right for v in row).most_common(1)[0][0]
    return [[3 if left[r][c] == right[r][c] else mismatch
             for c in range(len(left[r]))] for r in range(h)]


