    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if grid[r][c] == background:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if grid[r][c] == background:
                out[r][c] = 2

    # Fill short holes between aligned marks within the figure.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == color]
        for a, b in zip(cols, cols[1:]):
            if b - a <= 4:
