    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    markers = {v for row in grid for v in row if v != background}
    if not markers:
        return [row[:] for row in grid]
    marker = next(iter(markers))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0 = min(r for r, c in pts)
    r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts)
    c1 = max(c for r, c in pts)
    out = [row[:] for row in grid]

    # Close the perimeter of the marker bounding box.
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if grid[r][c] == background:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if grid[r][c] == background:
                out[r][c] = 2

    # Continue short, axis-aligned fragmented strokes. The completed frame is
    # also an endpoint; only gaps with endpoint separation at most 3 are closed.
    anchors = [[grid[r][c] == marker or out[r][c] == 2 for c in range(w)] for r in range(h)]
    for r in range(h):
        cols = [c for c in range(w) if anchors[r][c]]
        for a, b in zip(cols, cols[1:]):
            if b - a <= 3:
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if anchors[r][c]]
        for a, b in zip(rows, rows[1:]):
            if b - a <= 3:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out


