from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the repeated horizontal palette strip: same row repeated, with
    # a contiguous run of nonzero colors in each row.
    palette = None
    for r in range(h):
        row = grid[r]
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            a = c
            while c < w and row[c] != 0:
                c += 1
            seq = row[a:c]
            if len(seq) < 2:
                continue
            end = r + 1
            while end < h and grid[end][a:c] == seq:
                end += 1
            if end - r >= 2:
                palette = (seq, r, end, a, c)
                break
        if palette:
            break
    if palette is None:
        return [row[:] for row in grid]
    seq, pr0, pr1, pc0, pc1 = palette
    center_color = 1 if 1 in seq else seq[len(seq)//2]
    center_idx = seq.index(center_color)

    # Extract the connected motif of the central palette color, excluding the strip.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != center_color or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == center_color:
                        seen.add((yy, xx)); q.append((yy, xx))
            if any(not (pr0 <= y < pr1 and pc0 <= x < pc1) for y, x in comp):
                components.append(comp)
    if not components:
        return [row[:] for row in grid]
    # Use the largest central-color object as the motif.
    comp = max(components, key=len)
    r0 = min(y for y, x in comp); c0 = min(x for y, x in comp)
    r1 = max(y for y, x in comp) + 1
    points = [(y-r0, x-c0) for y, x in comp]
    step = r1 - r0
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(seq):
        dr = (i - center_idx) * step
        for dy, dx in points:
            y, x = r0 + dr + dy, c0 + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out

